def generate(seed):
    r = random.Random(seed)
    while True:
        R = r.choice([3, 3, 3, 4])
        g = [r.randint(2, 6 if R < 4 else 4) for _ in range(R)]
        if len(set(g)) > 1 and 6 <= sum(g) <= 11:
            break
    while True:
        d = [r.choice([1, 1, 1, 2, 2, 2, 2, 3]) for _ in range(R - 1)]
        if R > 3 and r.random() < 0.35:
            d[r.randrange(R - 1)] = 0
        if 2 <= sum(d) <= R + 1 and d.count(3) < 2:
            break
    return str(r.randint(26, 30)) + "/" + "".join(map(str, g)) + "/" + "".join(map(str, d))

